  (** The single [vm_compute] certificate: every entry's root squares to that
      entry's argument, in the shared checker's raw [forallb] shape.  It reads
      the window points from the table leaf's [full_table_reduced] literal, so
      the octupling chain is not rebuilt here — only one field multiplication
      per entry, and no [modpow]. *)
  Lemma root_check_true :
    List.forallb
      (fun w : nat =>
         List.forallb
           (FixedBaseSignCert.root_check_fn table default
              ValueCommitVFullTable.full_table_reduced root_table w)
           (List.seq 0 8))
      (List.seq 0 22) = true.
  Proof. vm_cast_no_check (@eq_refl bool true). Qed.

  (** Per-entry extraction of the positive QR fact, consumed by the ladder
      file as the [Hqr] hypothesis of [window_y_forced_of_disc]. *)
  Lemma y_check_entry (w i : nat) (Hw : (w < 22)%nat) (Hi : (i < 8)%nat) :
    is_square
      (UnOp.from
         (EccSpec.fw_z (List.nth w table default)
          +F Point.y
               (PallasModel.repr
                  (List.nth i (List.nth w ValueCommitVFullTable.full_table [])
                     Pallas.identity)))) = true.
  Proof.
    exact (FixedBaseSignCert.y_check_entry table default
             ValueCommitVFullTable.full_table ValueCommitVFullTable.full_table_reduced
             root_table 22 ValueCommitVFullTable.full_table_reduced_eq
             root_check_true w i Hw Hi).
  Qed.
End ValueCommitVWindowSignCert.
